    adcs_quat_t q_hat, next;
    double theta, half, norm_w, s;

    // 1. Null check
    if ((q == NULL) || (w == NULL) || (out == NULL)) {
        if (out != NULL) *out = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
        return ADCS_E_NULL;
    }

    // 2. Range check
    if ((!adcs_is_finite_vec3(w)) || (!isfinite(dt)) || (dt < 0.0)) {
        *out = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
        return ADCS_E_RANGE;
    }

    // 3. Normalize input quaternion
    if (adcs_quat_normalize(q, &q_hat) != ADCS_OK) {
        *out = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
        return ADCS_E_DEGENERATE;
    }

    // 4. Calculate angle
    norm_w = adcs_vec3_norm(w);
    theta = norm_w * dt;

    // 5. Build delta quaternion dq
    adcs_quat_t dq;
    if (theta <= ADCS_EPS_NORM) {
        // Small angle approximation: cos(theta/2) ~ 1, sin(theta/2)/||w|| ~ dt/2
        dq = (adcs_quat_t){1.0, 0.5 * w->x * dt, 0.5 * w->y * dt, 0.5 * w->z * dt};
    } else {
        half = 0.5 * theta;
        s = sin(half) / norm_w;
        dq = (adcs_quat_t){cos(half), s * w->x, s * w->y, s * w->z};
    }

    // 6. Propagate: next = dq * q_hat
    next = adcs_quat_multiply(&dq, &q_hat);

    // 7. Normalize and canonicalize (w >= 0)
    if (adcs_quat_normalize(&next, out) != ADCS_OK) {
        *out = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
        return ADCS_E_DEGENERATE;
    }

    if (out->w < 0.0) {
        out->w = -out->w;
        out->x = -out->x;
        out->y = -out->y;
        out->z = -out->z;
    }

    return ADCS_OK;
}

